PATHS={'home':'/','game':'/game1/','privacy':'/game1/privacy/','terms':'/game1/terms/','support':'/support/','siteprivacy':'/privacy/'}
def paragraph(text):
 s=esc(text)
 for target in ['policies.google.com/privacy','policies.google.com/technologies/ads']:
  s=s.replace(target,f'<a href="https://{target}" rel="external">{target}</a>')
 return '<p>'+s+'</p>'
def grid(t):
 cells=''.join('<span class="cell '+('lit' if i in [1,3,4,5,7] else '')+'">'+('✦' if i==4 else '')+'</span>' for i in range(9))
 return '<div class="puzzle-art" role="img" aria-label="'+esc(t['gridlabel'])+'"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="board">'+cells+'</div><span class="art-note">3 × 3 / LIGHTS OUT</span></div>'
def shell(kind,lang,body,title):
 t=TEXT[lang];path=PATHS[kind];other='vi' if lang=='en' else 'en';canonical=BASE+url(path,lang)
 nav=''.join(f'<a href="{url("/#games" if k=="game" else PATHS[k],lang)}"'+(' aria-current="page"' if kind==k else '')+'>'+esc(n)+'</a>' for k,n in zip(['game','siteprivacy','support'],[('Trò chơi' if lang=='vi' else 'Games'),t['privacy'],t['support']]))
 footer=''.join(f'<a href="{url(PATHS[k],lang)}">{esc(t["privacy"] if k=="siteprivacy" else t[k])}</a>' for k in ['siteprivacy','terms','support'])
 desc=('Ứng dụng và trò chơi từ DVK. Khám phá các dự án và tìm hỗ trợ.' if lang=='vi' else 'Mobile apps and games by DVK. Explore our projects and find support.') if kind=='home' else t.get(kind+'lead',t['game_intro'])
 return f'''<!doctype html>
<html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} · DVK</title><meta name="description" content="{esc(desc)}"><meta name="theme-color" content="#173e30"><link rel="canonical" href="{canonical}"><link rel="alternate" hreflang="en" href="{BASE+path}"><link rel="alternate" hreflang="vi" href="{BASE+url(path,'vi')}"><link rel="alternate" hreflang="x-default" href="{BASE+path}"><meta property="og:title" content="{esc(title)} · DVK"><meta property="og:description" content="{esc(desc)}"><meta property="og:url" content="{canonical}"><meta property="og:type" content="website"><meta property="og:image" content="{BASE}/assets/puzzle-spark-icon.png"><link rel="icon" type="image/svg+xml" href="/assets/spark.svg"><link rel="stylesheet" href="/assets/site.css"></head><body><a class="skip" href="#main">{'Skip to content' if lang=='en' else 'Đến nội dung'}</a><header><a class="brand" href="{url('/',lang)}" aria-label="DVK home"><img src="/assets/spark.svg" alt="" width="34" height="34">DVK</a><nav aria-label="{'Main navigation' if lang=='en' else 'Điều hướng chính'}">{nav}<a class="language" href="{url(path,other)}" lang="{other}" hreflang="{other}">{esc(t['lang'])}</a></nav></header><main id="main">{body}</main><footer><div><a class="brand" href="{url('/',lang)}">DVK</a><p>{esc(t['foot'])}</p><a href="mailto:game@dvk.vn">game@dvk.vn</a></div><div class="footer-links">{footer}</div><small>© 2026 DVK · Apps & Games</small></footer></body></html>'''
def home(lang):
 t=TEXT[lang];vi=lang=='vi'
 title='Ý tưởng nhỏ.<br>Trải nghiệm đáng nhớ.' if vi else 'Small ideas.<br>Memorable experiences.'
 intro='DVK phát triển ứng dụng và trò chơi cho thiết bị di động. Khám phá các dự án, tìm hiểu từng game và nhận hỗ trợ trực tiếp tại đây.' if vi else 'DVK builds mobile apps and games. Explore our projects, get to know each game, and find direct support in one place.'
 hero='<section class="hero studio-hero"><div class="hero-copy"><p class="eyebrow">DVK / '+('ỨNG DỤNG & TRÒ CHƠI' if vi else 'APPS & GAMES')+'</p><h1>'+title+'</h1><p class="lead">'+intro+'</p><div class="actions"><a class="button" href="#games">'+('Khám phá dự án' if vi else 'Explore our projects')+' <span aria-hidden="true">↘</span></a><a class="text-link" href="'+url(PATHS['support'],lang)+'">'+t['contact']+' →</a></div></div><div class="studio-art" aria-hidden="true"><div class="studio-card studio-back"></div><div class="studio-card studio-front"><img src="/assets/spark.svg" alt="" width="65" height="65"><strong>DVK<span>✦</span></strong><small>IDEAS INTO EXPERIENCES</small></div></div></section>'
 heading='Ứng dụng & trò chơi' if vi else 'Apps & games'
 project='<section id="games" class="projects"><div class="project-heading"><p class="eyebrow">'+('KHÁM PHÁ CÙNG DVK' if vi else 'DISCOVER DVK')+'</p><h2>'+heading+'</h2></div><article class="project-card"><div class="project-copy"><div class="project-identity"><img src="/assets/puzzle-spark-icon.png" width="72" height="72" alt="Puzzle Spark"><div><span class="project-index">01 / LIGHTS OUT</span><h3>Puzzle Spark</h3></div></div><p>'+esc(t['game_intro'])+'</p><div class="project-facts"><span>240 '+('màn' if vi else 'puzzles')+'</span><span>24 '+('tầng' if vi else 'tiers')+'</span><span>5 '+('ngôn ngữ' if vi else 'languages')+'</span></div><a class="button" href="'+url(PATHS['game'],lang)+'">'+esc(t['explore'])+' ↗</a><p class="project-status">'+esc(t['status'])+'</p></div>'+grid(t)+'</article></section>'
 items=[('Dành cho thiết bị di động','Trải nghiệm được xây dựng cho Android và iOS. Thông tin nền tảng phát hành nằm trên trang riêng của mỗi ứng dụng.'),('Thông tin rõ ràng','Mỗi game có hướng dẫn, chính sách quyền riêng tư và điều khoản riêng để bạn dễ tìm hiểu.'),('Hỗ trợ trực tiếp','Bạn có thể gửi câu hỏi, báo lỗi hoặc góp ý tới game@dvk.vn.')] if vi else [('Built for mobile','Experiences built for Android and iOS. Available platforms are listed on each app’s own page.'),('Clear information','Find instructions, privacy information and terms on each game’s dedicated page.'),('Direct support','Send questions, bug reports or feedback to game@dvk.vn.')]
 features='<section class="features">'+''.join('<article><span class="feature-number">0'+str(i+1)+'</span><h3>'+esc(a)+'</h3><p>'+esc(b)+'</p></article>' for i,(a,b) in enumerate(items))+'</section>'
 return hero+project+features

def siteprivacy(lang):
 t=TEXT[lang];vi=lang=='vi'
 title='Quyền riêng tư trên dvk.vn' if vi else 'Privacy on dvk.vn'
 intro='Chính sách dành cho website giới thiệu DVK. Mỗi ứng dụng có chính sách dữ liệu riêng.' if vi else 'Privacy information for the DVK website. Each app has its own data policy.'
 return '<section class="page-head legal-head"><p class="eyebrow">DVK / 16 OCT 2026</p><h1>'+title+'</h1><p class="lead">'+intro+'</p></section><div class="legal-body"><section><h2>'+esc(t['webtitle'])+'</h2>'+paragraph(t['webbody'])+'<p><a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub Privacy</a> · <a href="https://www.cloudflare.com/privacypolicy/">Cloudflare Privacy</a></p></section><section><h2>'+('Quyền riêng tư từng ứng dụng' if vi else 'App-specific privacy')+'</h2><p><a href="'+url(PATHS['privacy'],lang)+'">Puzzle Spark — '+esc(t['privacy'])+'</a></p></section><section><h2>'+esc(t['contact'])+'</h2><p><a href="mailto:game@dvk.vn">game@dvk.vn</a></p></section></div>'

def game(lang):
 t=TEXT[lang];sections=[(t['gamelead'],t['details']),(t['hints'],t['hintbody']),(t['five'],t['fivebody'])]
 rows=''.join('<section class="detail-row"><h2>'+esc(a)+'</h2><p>'+esc(b)+'</p></section>' for a,b in sections)
 helptext=''.join('<details><summary>'+esc(a)+'</summary>'+paragraph(b)+'</details>' for a,b in DATA['help'][lang])
 return f'''<section class="page-head game-page-head"><div><p class="eyebrow">PUZZLE SPARK</p><h1>{esc(t['gamelead'])}</h1><p class="lead">{esc(t['game_intro'])}</p><span class="pill">{esc(t['status'])}</span><p class="quiet">{'Đang chuẩn bị phát hành Android. Chưa công bố lịch phát hành iOS.' if lang=='vi' else 'Android release in preparation. No public iOS release date has been announced.'}</p></div>{grid(t)}</section><div class="detail-wrap">{rows}<section class="help"><h2>{esc(t['how'])}</h2>{helptext}</section><p class="quiet">{esc(t['notmoney'])}</p><a class="button" href="{url(PATHS['support'],lang)}">{esc(t['contact'])} ↗</a></div>'''
def legal(kind,lang):
 t=TEXT[lang];sections=''.join('<section id="section-'+str(i+1)+'"><h2>'+esc(a)+'</h2>'+paragraph(b)+'</section>' for i,(a,b) in enumerate(DATA[kind][lang]))
 web='<section><h2>'+esc(t['webtitle'])+'</h2>'+paragraph(t['webbody'])+'<p><a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub Privacy</a> · <a href="https://www.cloudflare.com/privacypolicy/">Cloudflare Privacy</a></p></section>' if kind=='privacy' else ''
 return f'''<section class="page-head legal-head"><p class="eyebrow">PUZZLE SPARK · {esc(t['legalnote'])}</p><h1>{esc(t[kind+'title'])}</h1><p class="lead">{esc(t[kind+'lead'])}</p><p class="provider">{esc(t['provider'])}</p></section><div class="legal-body">{sections}{web}<a class="text-link" href="{url(PATHS['support'],lang)}">{esc(t['contact'])} →</a></div>'''
def support(lang):
 t=TEXT[lang];rows=''.join('<section><h2>'+esc(t[a])+'</h2><p>'+esc(t[b])+'</p></section>' for a,b in [('reporttitle','report'),('savedtitle','saved'),('notifytitle','notify')])
 return f'''<section class="page-head"><p class="eyebrow">DVKAPP / PUZZLE SPARK</p><h1>{esc(t['supporttitle'])}</h1><p class="lead">{esc(t['supportlead'])}</p></section><div class="support-layout"><aside class="contact-card"><img src="/assets/spark.svg" width="56" height="56" alt=""><h2>{esc(t['email'])}</h2><a class="email" href="mailto:game@dvk.vn?subject=Puzzle%20Spark%20support">game@dvk.vn ↗</a><p>{esc(t['provider'])}</p></aside><div class="support-copy">{rows}</div></div>'''
for lang in ['en','vi']:
 for kind,path in PATHS.items():
  body=home(lang) if kind=='home' else game(lang) if kind=='game' else support(lang) if kind=='support' else siteprivacy(lang) if kind=='siteprivacy' else legal(kind,lang)
  title=('DVK — Ứng dụng & trò chơi' if lang=='vi' else 'DVK — Apps & Games') if kind=='home' else 'Puzzle Spark' if kind=='game' else ('Quyền riêng tư website' if lang=='vi' else 'Website privacy') if kind=='siteprivacy' else TEXT[lang][kind+'title']
  dest=OUT/url(path,lang).lstrip('/');dest.mkdir(parents=True,exist_ok=True);(dest/'index.html').write_text(shell(kind,lang,body,title))
(OUT/'app-ads.txt').write_text('google.com, pub-3636940103463538, DIRECT, f08c47fec0942fa0\n')
(OUT/'CNAME').write_text('dvk.vn\n');(OUT/'.nojekyll').touch()
(OUT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: https://dvk.vn/sitemap.xml\n')
locs=[BASE+url(p,l) for l in ['en','vi'] for p in PATHS.values()]
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+x+'</loc></url>' for x in locs)+'</urlset>')
(OUT/'404.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Page not found · DVK</title><link rel="stylesheet" href="/assets/site.css"><main class="page-head"><p class="eyebrow">404</p><h1>A different path.</h1><p>This page could not be found.</p><a class="button" href="/">Back to DVKapp</a></main></html>')
print('Built',len(locs),'pages and app-ads.txt in',OUT)

# GitHub Pages branch publishing serves only /docs, keeping source separate.
pages = ROOT / "docs"
if pages.exists(): shutil.rmtree(pages)
shutil.copytree(OUT, pages)
